<script setup lang="ts">
import MoneyInput from './MoneyInput.vue';
import { computed, reactive, ref, watch } from 'vue';
import { state, mutate, mutation, today } from '../store.ts';
import { id, calculateShares, money, normalize, localDay, duplicateCandidates, type Bill, type Review, type Transaction } from '../domain.ts';
import { fromZonedTime } from '../timezone.ts';
import Icon from './Icon.vue';
const props = defineProps<{ existing?: Bill; review?: Review; transaction?: Transaction }>();
const emit = defineEmits<{ saved: []; dirty: [value: boolean] }>();
const form = reactive({ title: props.existing?.title ?? props.transaction?.merchant ?? props.review?.merchant.value ?? '', total: props.existing?.total ?? props.transaction?.amount ?? props.review?.amount.value ?? '', category: props.existing?.categoryID ?? props.transaction?.categoryID ?? state.data.categories.find(row => row.kind === 'expense' && !row.archived)?.id ?? '', account: props.existing?.payer.selfPaid?.accountID ?? props.transaction?.accountID ?? state.data.accounts.find(row => !row.archived)?.id ?? '', payer: props.existing?.payer.other?.memberID ?? 'self', date: (props.existing ? localDay(props.existing.occurredAt, state.timezone) : undefined) ?? props.review?.date.value ?? today(), method: props.existing ? 'amount' : 'equal', note: props.existing?.note ?? '' });
const members = ref(props.existing?.members.map(row => ({ id: row.id, name: row.displayName, self: row.isSelf, value: row.shareAmount })) ?? [{ id: id(), name: 'Saya', self: true, value: '0' }]);
const error = ref('');
const duplicateConfirmed = ref(false);
const candidates = computed(() => props.review ? duplicateCandidates(state.data, { ...props.review, amount: { ...props.review.amount, value: form.total }, merchant: { ...props.review.merchant, value: form.title }, date: { ...props.review.date, value: form.date } }, form.payer === 'self' ? form.account : '') : []);
const shares = computed(() => { try { return calculateShares(form.total, members.value, form.method); } catch { return null; } });
watch([form, members], () => emit('dirty', true), { deep: true });
async function save() {
  error.value = '';
  if (members.value.length < 2) { error.value = 'Tambahkan minimal satu orang untuk membagi tagihan.'; return; }
  if (candidates.value.length && !duplicateConfirmed.value) { error.value = 'Periksa tagihan/transaksi mirip sebelum menyimpan.'; return; }
  if (!shares.value) { error.value = 'Periksa nominal dan porsi: jumlah porsi harus sama dengan total; persentase tepat 100%.'; return; }
  if (new Set(members.value.map(row => normalize(row.name))).size !== members.value.length) { error.value = 'Nama peserta tidak boleh sama.'; return; }
  const payload: Record<string, unknown> = { ...mutation(), p_total: form.total, p_title: form.title, p_payer_kind: form.payer === 'self' ? 'self' : 'other', p_payer_member_id: form.payer === 'self' ? null : form.payer, p_payer_account_id: form.payer === 'self' ? form.account : null, p_category_id: form.category, p_occurred_at: props.existing && localDay(props.existing.occurredAt, state.timezone) === form.date ? props.existing.occurredAt : fromZonedTime(form.date, state.timezone), p_members: members.value.map((row, index) => ({ id: row.id, display_name: row.name, is_self: row.self, share_amount: shares.value![row.id], sort_order: index })), p_note: form.note || null };
  const operation = props.existing ? 'update_split_bill' : props.review ? 'create_split_bill_from_review' : props.transaction ? 'convert_transaction_to_split_bill' : 'create_split_bill';
  if (props.existing) { payload.p_split_bill_id = props.existing.id; payload.p_expected_version = props.existing.version; }
  if (props.transaction) { payload.p_transaction_id = props.transaction.id; payload.p_expected_version = props.transaction.version; }
  if (props.review) { payload.p_review_item_id = props.review.id; payload.p_client_mutation_id = props.review.id; }
  if (await mutate(operation, payload, 'Tagihan bersama tersimpan')) { emit('dirty', false); emit('saved'); }
}
</script>
<template><form class="entry-form" @submit.prevent="save"><label>Nama tagihan<input v-model="form.title" required maxlength="160" placeholder="Misalnya, makan bersama"></label><label class="amount-input">Total tagihan<div><span>Rp</span><MoneyInput v-model="form.total" aria-label="Total tagihan" required placeholder="120.000" /></div></label><div class="form-grid"><label>Metode pembagian<select v-model="form.method"><option value="equal">Sama rata</option><option value="amount">Nominal</option><option value="percentage">Persentase</option></select></label><label>Pembayar<select v-model="form.payer"><option value="self">Saya</option><option v-for="member in members.filter(row => !row.self)" :key="member.id" :value="member.id">{{ member.name }}</option></select></label></div><section class="members"><div class="section-heading"><h3>Peserta <span class="muted">{{ members.length }}/20</span></h3><button type="button" class="icon-button" aria-label="Tambah peserta" :disabled="members.length >= 20" @click="members.push({ id: id(), name: '', self: false, value: '0' })"><Icon name="plus" :size="20" /></button></div><div v-for="(member, index) in members" :key="member.id" class="member-row"><span class="avatar peach">{{ member.name.charAt(0) || '?' }}</span><label class="sr-only" :for="`name-${member.id}`">Nama peserta {{ index + 1 }}</label><input :id="`name-${member.id}`" v-model="member.name" :readonly="member.self" required maxlength="80" :placeholder="`Teman ${index}`"><template v-if="form.method !== 'equal'"><label class="sr-only" :for="`share-${member.id}`">{{ form.method === 'percentage' ? 'Persentase' : 'Porsi' }} {{ member.name }}</label><input v-if="form.method === 'percentage'" :id="`share-${member.id}`" v-model="member.value" type="number" min="0" :max="form.method === 'percentage' ? 100 : 999999999999" :step="form.method === 'percentage' ? 0.01 : 1" required class="share-input"><MoneyInput v-else :id="`share-${member.id}`" v-model="member.value" required class="share-input" /></template><span v-else class="member-share">{{ shares ? money(shares[member.id]) : '—' }}</span><button v-if="!member.self" type="button" class="icon-button" :aria-label="`Hapus peserta ${member.name}`" @click="members.splice(index, 1); form.payer = 'self'"><Icon name="close" :size="16" /></button></div></section><div class="form-grid"><label v-if="form.payer === 'self'">Akun pembayaran<select v-model="form.account" required><option v-for="account in state.data.accounts.filter(row => !row.archived)" :key="account.id" :value="account.id">{{ account.name }}</option></select></label><label>Kategori<select v-model="form.category" required><option v-for="category in state.data.categories.filter(row => !row.archived && row.kind === 'expense')" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label>Tanggal<input v-model="form.date" type="date" required></label></div><label>Catatan <span class="optional">opsional</span><textarea v-model="form.note" rows="2" maxlength="2000"></textarea></label><div v-if="shares" class="callout peach"><strong>{{ form.payer === 'self' ? 'Saya membayar' : 'Teman membayar' }} {{ money(form.total) }}</strong><p>Bagian saya {{ money(shares[members.find(row => row.self)!.id]) }}. {{ form.payer === 'self' ? 'Porsi teman menjadi piutang, bukan pengeluaran pribadi.' : 'Bagian saya menjadi utang; saldo akun belum berubah.' }}</p></div><div v-if="candidates.length" class="callout sun"><strong>Ditemukan transaksi mirip. Periksa sebelum menyimpan.</strong><p v-for="candidate in candidates" :key="candidate.id">{{ candidate.merchant }} · {{ money(candidate.amount) }}</p><label class="checkbox"><input v-model="duplicateConfirmed" type="checkbox"> Saya sudah memeriksa; ini tagihan berbeda.</label></div><p v-if="error || state.error" role="alert" class="error-text">{{ error || state.error }}</p><button class="primary full" :disabled="state.saving || (!state.online && state.mode !== 'demo')"><Icon name="check" />{{ state.saving ? 'Menyimpan…' : 'Simpan tagihan' }}</button></form></template>
